// ── COMPONENTS ─────────────────────────────────────────────────

function Toast({ msg, onDone }) {
  useEffect(() => { const t = setTimeout(onDone, 3000); return () => clearTimeout(t); }, []);
  return <div className="toast">{msg}</div>;
}

function EmailModal({ project, rooms, preparedBy, operatorEmail, operatorName, onClose }) {
  const safeName   = (project.name        || 'Quote').replace(/[^a-zA-Z0-9_\- ]/g, '').trim() || 'Quote'
  const safeClient = (project.contactName || '').replace(/[^a-zA-Z0-9_\- ]/g, '').trim()
  const defaultFilename = (safeClient ? `${safeClient} — ${safeName}` : safeName) + ' — Quote.pdf'

  const defaultBody = [
    `Hi ${project.contactName || 'there'},`,
    '',
    `Please find attached your quote for ${project.name}.`,
    '',
    `Project Address: ${project.address || '—'}`,
    `Bid Date: ${fmtDate(project.bidDate || '')}`,
    `Quote ID: ${fmtId(project.id)}`,
    '',
    "Please don't hesitate to reach out with any questions.",
    '',
    'Best regards,',
    'Engstrom Wood Products',
  ].join('\n')

  const [to,      setTo]      = useState(project.email || '')
  const [subject, setSubject] = useState(`Quote: ${project.name}`)
  const [body,    setBody]    = useState(defaultBody)
  const [status,  setStatus]  = useState('idle') // idle | generating | sending | done | error
  const [errMsg,  setErrMsg]  = useState('')

  const busy = status === 'generating' || status === 'sending'

  const handleSend = async () => {
    if (!to.trim()) { setErrMsg('Recipient email is required.'); return }
    setErrMsg('')
    setStatus('generating')
    try {
      const blob = await buildCustomerPDFBlob(project, rooms, preparedBy)
      setStatus('sending')

      // Convert blob → base64
      const arrayBuf = await blob.arrayBuffer()
      const uint8    = new Uint8Array(arrayBuf)
      let binary = ''
      for (let i = 0; i < uint8.length; i++) binary += String.fromCharCode(uint8[i])
      const pdfBase64 = btoa(binary)

      const { error } = await supabase.functions.invoke('send-quote-email', {
        body: {
          to: to.trim(),
          subject: subject.trim(),
          body: body.trim(),
          pdfBase64,
          filename: defaultFilename,
          replyTo: operatorEmail || undefined,
          fromName: operatorName ? `${operatorName} from EWP` : undefined,
        },
      })
      if (error) {
        let msg = error.message || 'Send failed'
        try { const b = await error.context?.json?.(); if (b?.error) msg = b.error } catch {}
        throw new Error(msg)
      }
      setStatus('done')
    } catch (err) {
      setErrMsg(err.message || 'Something went wrong.')
      setStatus('error')
    }
  }

  const overlayStyle = {
    position: 'fixed', inset: 0, zIndex: 9000,
    background: 'rgba(20,16,10,0.55)', backdropFilter: 'blur(4px)',
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    padding: 16,
  }
  const boxStyle = {
    background: 'var(--card-bg, #fff)',
    border: '1px solid var(--border, #EDE8DF)',
    borderRadius: 14,
    padding: '32px 28px 24px',
    width: '100%', maxWidth: 500,
    boxShadow: '0 8px 40px rgba(0,0,0,0.18)',
    fontFamily: "'DM Sans', sans-serif",
    display: 'flex', flexDirection: 'column', gap: 14,
  }
  const labelStyle = { fontSize: 11, fontWeight: 700, color: 'var(--mid, #9B8E82)',
    textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 4, display: 'block' }
  const inputStyle = {
    width: '100%', boxSizing: 'border-box',
    border: '1px solid var(--border, #DDD5C8)', borderRadius: 7,
    padding: '8px 10px', fontSize: 13, fontFamily: 'inherit',
    background: 'var(--input-bg, #FDFAF5)', color: 'var(--text, #2A2118)',
    outline: 'none',
  }

  if (status === 'done') return (
    <div style={overlayStyle} onClick={onClose}>
      <div style={{ ...boxStyle, alignItems: 'center', textAlign: 'center', gap: 12 }}
        onClick={e => e.stopPropagation()}>
        <div style={{ fontSize: 42 }}>✅</div>
        <div style={{ fontSize: 17, fontWeight: 700, color: 'var(--text)' }}>Email sent!</div>
        <div style={{ fontSize: 13, color: 'var(--mid)' }}>Quote delivered to <strong>{to}</strong></div>
        <button className="btn btn-gold" style={{ marginTop: 8 }} onClick={onClose}>Close</button>
      </div>
    </div>
  )

  return (
    <div style={overlayStyle} onClick={onClose}>
      <div style={boxStyle} onClick={e => e.stopPropagation()}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ fontSize: 16, fontWeight: 700, color: 'var(--text)' }}>✉ Email Quote to Client</div>
          <button onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer',
            fontSize: 20, color: 'var(--mid)', lineHeight: 1 }} aria-label="Close">×</button>
        </div>

        <div>
          <label style={labelStyle}>To</label>
          <input style={inputStyle} type="email" value={to} onChange={e => setTo(e.target.value)}
            placeholder="client@email.com" disabled={busy} />
        </div>

        <div>
          <label style={labelStyle}>Subject</label>
          <input style={inputStyle} type="text" value={subject} onChange={e => setSubject(e.target.value)}
            disabled={busy} />
        </div>

        <div>
          <label style={labelStyle}>Message</label>
          <textarea style={{ ...inputStyle, minHeight: 160, resize: 'vertical' }}
            value={body} onChange={e => setBody(e.target.value)} disabled={busy} />
        </div>

        <div style={{ fontSize: 11, color: 'var(--mid)', background: 'var(--bg, #FDFAF5)',
          border: '1px solid var(--border)', borderRadius: 6, padding: '7px 10px' }}>
          📎 <strong>{defaultFilename}</strong> will be attached automatically.
          {operatorEmail && <span> Replies go to <strong>{operatorEmail}</strong>.</span>}
        </div>

        {errMsg && <div style={{ fontSize: 12, color: 'var(--red, #C0392B)' }}>{errMsg}</div>}

        <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end', marginTop: 4 }}>
          <button className="btn btn-outline" onClick={onClose} disabled={busy}>Cancel</button>
          <button className="btn btn-gold" onClick={handleSend} disabled={busy} style={{ minWidth: 110 }}>
            {status === 'generating' ? '⏳ Building PDF…'
              : status === 'sending'  ? '📤 Sending…'
              : '✉ Send Email'}
          </button>
        </div>
      </div>
    </div>
  )
}

function Field({ label, error, children, hint }) {
  // Auto-generate id from label for htmlFor association
  const fieldId = label
    ? `f-${label.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '')}`
    : undefined

  // Try to inject id into the single child input/select
  let kid = children
  try {
    const only = React.Children.only(children)
    if (fieldId && only && !only.props.id) kid = React.cloneElement(only, { id: fieldId })
  } catch { /* multiple children — skip injection */ }

  return (
    <div className="field">
      {label && (
        <label className="field-label" htmlFor={fieldId}>
          {label}
          {hint && (
            <abbr title={hint} aria-label={hint}
              style={{ marginLeft: 5, fontSize: '0.82em', cursor: 'help',
                textDecoration: 'underline dotted', color: 'var(--mid)' }}>ⓘ</abbr>
          )}
        </label>
      )}
      {kid}
      {error && <span className="field-error" role="alert">{error}</span>}
    </div>
  );
}

// ── PROJECT SETUP PAGE ─────────────────────────────────────────
function ProjectSetup({ project, onChange, onNext }) {
  const [errors, setErrors] = useState({});

  const validate = () => {
    const e = {};
    if (!project.name) e.name = "Required";
    if (!project.address) e.address = "Required";
    if (!project.bidDate) e.bidDate = "Required";
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleNext = () => { if (validate()) onNext(); };

  return (
    <div>
      <div className="page-header">
        <div className="page-title">Project Details</div>
        <div className="gold-rule" />
        <div className="page-subtitle">Enter the project and client information to get started.</div>
      </div>

      <div className="card">
        <div className="card-header"><span className="card-title">CLIENT INFORMATION</span></div>
        <div className="card-body">
          <div className="form-grid form-grid-2">
            <Field label="Project Name" error={errors.name}>
              <input aria-label="Project name" className={errors.name ? "error" : ""} value={project.name} placeholder="e.g. Johnson Kitchen Remodel"
                onChange={e => onChange({ name: e.target.value })} />
            </Field>
            <Field label="Project Address" error={errors.address}>
              <input aria-label="Project address" className={errors.address ? "error" : ""} value={project.address} placeholder="123 Main St, Minneapolis MN"
                onChange={e => onChange({ address: e.target.value })} />
            </Field>
            <Field label="Contact Name">
              <input value={project.contactName} placeholder="Full name"
                onChange={e => onChange({ contactName: e.target.value })} />
            </Field>
            <Field label="Contact Phone">
              <input
                value={project.contactPhone}
                placeholder="(612) 555-0100"
                maxLength={14}
                onChange={e => {
                  const digits = e.target.value.replace(/\D/g, "").slice(0, 10)
                  let formatted = ""
                  if (digits.length === 0) formatted = ""
                  else if (digits.length <= 3) formatted = `(${digits}`
                  else if (digits.length <= 6) formatted = `(${digits.slice(0,3)}) ${digits.slice(3)}`
                  else formatted = `(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`
                  onChange({ contactPhone: formatted })
                }}
              />
            </Field>
            <Field label="Email Address">
              <input aria-label="Email address" type="email" value={project.email} placeholder="client@email.com"
                onChange={e => onChange({ email: e.target.value })} />
            </Field>
            <Field label="Bid Date" error={errors.bidDate}>
              <input
                className={errors.bidDate ? "error" : ""}
                type="date"
                value={project.bidDate}
                onChange={e => onChange({ bidDate: e.target.value })}
              />
            </Field>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-header"><span className="card-title">CONTRACTOR DETAILS</span></div>
        <div className="card-body">
          <div className="form-grid form-grid-3">
            <Field label="Is there a Contractor?">
              <select value={project.contractorYN} onChange={e => onChange({ contractorYN: e.target.value })}>
                <option>No</option><option>Yes</option>
              </select>
            </Field>
            {project.contractorYN === "Yes" && <>
              <Field label="Contractor Name">
                <input value={project.contractorName} placeholder="Company name"
                  onChange={e => onChange({ contractorName: e.target.value })} />
              </Field>
              <Field label="Contractor Contact">
                <input value={project.contractorContact} placeholder="Phone or email"
                  onChange={e => {
                    const raw = e.target.value
                    // Only auto-format if it looks like a phone number (digits/spaces/parens/dashes only)
                    const isPhone = /^[\d\s()\-+]*$/.test(raw) && /\d/.test(raw)
                    if (isPhone) {
                      const digits = raw.replace(/\D/g, "").slice(0, 10)
                      let formatted = ""
                      if (digits.length === 0) formatted = ""
                      else if (digits.length <= 3) formatted = `(${digits}`
                      else if (digits.length <= 6) formatted = `(${digits.slice(0,3)}) ${digits.slice(3)}`
                      else formatted = `(${digits.slice(0,3)}) ${digits.slice(3,6)}-${digits.slice(6)}`
                      onChange({ contractorContact: formatted })
                    } else {
                      onChange({ contractorContact: raw })
                    }
                  }} />
              </Field>
            </>}
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-header"><span className="card-title">SCOPE</span></div>
        <div className="card-body">
          <div className="form-grid form-grid-2">
            <Field label="Master Adjustment %">
              <input type="number" step="0.1" value={project.masterAdj} placeholder="0"
                onChange={e => onChange({ masterAdj: e.target.value })} />
            </Field>
          </div>
        </div>
      </div>

      <div className="flex justify-between items-center mt-24">
        <button className="btn btn-gold btn-lg" onClick={handleNext}>
          Continue to Rooms →
        </button>
      </div>
    </div>
  );
}

// ── CABINETRY SECTION ──────────────────────────────────────────
function CabinetrySection({ items, masterAdj, onChange }) {
  const update = (i, field, val) => {
    const next = items.map((it, idx) => idx === i ? { ...it, [field]: val } : it);
    onChange(next);
  };
  const justAddedRef = useRef(false);
  const newRowRef = useRef(null);
  const addRow = () => {
    justAddedRef.current = true;
    onChange([...items, { ...blankCabRow(), adjPct: masterAdj != null ? String(masterAdj) : "" }]);
  };
  const removeRow = (i) => {
    if (items.length === 1) return;
    onChange(items.filter((_, idx) => idx !== i));
  };
  useEffect(() => {
    if (justAddedRef.current && newRowRef.current) {
      newRowRef.current.focus();
      justAddedRef.current = false;
    }
  }, [items.length]);

  const subTotal = calcCabinetry(items);

  return (
    <div className="card form-section-anim" style={{ marginBottom: 16 }}>
      <div className="section-banner" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ display: "flex", alignItems: "center", gap: 12 }}>CABINETRY
          <span style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 18, fontWeight: 700, color: "var(--gold)", letterSpacing: 0 }}>{fmt(subTotal)}</span>
        </span>
        <button className="btn btn-sm" style={{ background: "var(--gold)", color: "#fff", border: "none" }} onClick={addRow}>+ Add Row</button>
      </div>
      <div className="scrollable">
        <table className="data-table" aria-label="Cabinetry items">
          <thead>
            <tr>
              <th scope="col" style={{ width: 220 }}>Product Type</th>
              <th scope="col" style={{ width: 140 }}>Construction</th>
              <th scope="col" style={{ width: 130 }}>Wood Type</th>
              <th scope="col" style={{ width: 70 }}>
                <abbr title="Number of units to install">LF / Qty</abbr>
              </th>
              <th scope="col" style={{ width: 80 }}>
                <abbr title="Price adjustment % — positive = markup, negative = discount">% Adj</abbr>
              </th>
              <th scope="col" style={{ width: 120 }}>Line Total</th>
              <th scope="col" style={{ width: 140 }}>Notes</th>
              <th scope="col" style={{ width: 36 }} aria-label="Actions" />
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => {
              const prod = PRICING.woodwork.find(w => w.name === item.product);
              const con = PRICING.construction.find(c => c.name === item.construction);
              const wood = PRICING.wood.find(w => w.name === item.wood);
              const basePrice = prod ? prod.price : 0;
              const conPrem = con ? con.premium : 0;
              const woodPrem = wood ? wood.premium : 0;
              const stdPrice = basePrice * (1 + conPrem) * (1 + woodPrem);
              const qty = parseFloat(item.qty) || 0;
              const adjPct = parseFloat(item.adjPct) || 0;
              const lineTotal = stdPrice * qty * (1 + adjPct / 100);

              return (
                <tr key={i}>
                  <td>
                    <select
                      ref={i === items.length - 1 ? newRowRef : null}
                      aria-label={`Row ${i + 1} product type`}
                      value={item.product}
                      onChange={e => update(i, "product", e.target.value)}>
                      <option value="">— Select —</option>
                      {PRICING.woodwork.map(w => <option key={w.name}>{w.name}</option>)}
                    </select>
                    {item.product && stdPrice > 0 && (
                      <div style={{ fontSize: 13, color: "var(--gold)", marginTop: 4, fontWeight: 700 }}>{fmt(stdPrice)}/unit</div>
                    )}
                  </td>
                  <td>
                    <select value={item.construction} onChange={e => update(i, "construction", e.target.value)}>
                      {PRICING.construction.map(c => <option key={c.name}>{c.name}</option>)}
                    </select>
                  </td>
                  <td>
                    <select value={item.wood} onChange={e => update(i, "wood", e.target.value)}>
                      {PRICING.wood.map(w => <option key={w.name}>{w.name}</option>)}
                    </select>
                  </td>
                  <td><input type="number" min="0" step="0.5" value={item.qty} onChange={e => update(i, "qty", e.target.value)} /></td>
                  <td><input type="number" step="0.1" value={item.adjPct} placeholder="0" onChange={e => update(i, "adjPct", e.target.value)} /></td>
                  <td className="num-cell" style={{ fontFamily: "'Cormorant Garamond', serif", fontSize: 17, fontWeight: 700, color: item.product && qty > 0 ? "var(--gold)" : "var(--muted)" }}>
                    {item.product && qty > 0 ? fmt(lineTotal) : "—"}
                  </td>
                  <td><input value={item.notes} onChange={e => update(i, "notes", e.target.value)} placeholder="Notes…" /></td>
                  <td><button className="btn btn-ghost btn-sm" style={{ color: items.length > 1 ? "var(--red)" : "var(--rule)", cursor: items.length > 1 ? "pointer" : "default" }} onClick={() => removeRow(i)} title="Remove row">✕</button></td>
                </tr>
              );
            })}
            <tr className="total-row">
              <td colSpan={5} style={{ textAlign: "center", fontFamily: "'DM Sans',sans-serif", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.08em", color: "var(--mid)" }}>
                Cabinetry Total
              </td>
              <td className="num-cell">{fmt(subTotal)}</td>
              <td /><td />
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

